(function(){"use strict";var LANGUAGES=["en","ja","zh","es","ru"];var STORAGE_KEY="bit-rag-lang";var META={en:{title:"bit-rag — The Simplest Local RAG API Server",description:"bit-rag is the simplest local RAG API server. FastAPI + LangChain + ChromaDB + Ollama, no database or web server setup required. Self-hosted, private, and ready in minutes."},ja:{title:"bit-rag ― 最もシンプルなローカルRAG APIサーバー",description:"bit-ragは最もシンプルなローカルRAG APIサーバー。FastAPI + LangChain + ChromaDB + Ollamaで、データベースやWebサーバーの構築不要。セルフホストでプライベート、数分で利用開始。"},zh:{title:"bit-rag — 最简单的本地 RAG API 服务器",description:"bit-rag 是最简单的本地 RAG API 服务器。基于 FastAPI + LangChain + ChromaDB + Ollama，无需搭建数据库或 Web 服务器。自托管、私密，几分钟即可就绪。"},es:{title:"bit-rag: el servidor API RAG local más simple",description:"bit-rag es el servidor API RAG local más simple. FastAPI + LangChain + ChromaDB + Ollama, sin necesidad de configurar base de datos ni servidor web. Autoalojado, privado y listo en minutos."},ru:{title:"bit-rag — простейший локальный RAG API-сервер",description:"bit-rag — простейший локальный RAG API-сервер. FastAPI + LangChain + ChromaDB + Ollama, без настройки базы данных или веб-сервера. Полностью автономный, приватный и готов за считанные минуты."}};function detectLanguage(){var saved=localStorage.getItem(STORAGE_KEY);if(saved&&LANGUAGES.indexOf(saved)!==-1)return saved;var nav=(navigator.language||"en").slice(0,2).toLowerCase();return LANGUAGES.indexOf(nav)!==-1?nav:"en"}function applyMeta(lang){var meta=META[lang]||META.en;document.title=meta.title;var descTag=document.querySelector('meta[name="description"]');if(descTag)descTag.setAttribute("content",meta.description)}var ml=new MultilanguageJS({languages:LANGUAGES,defaultLanguage:"en"});function setLanguage(lang){ml.setLanguage(lang);applyMeta(lang);localStorage.setItem(STORAGE_KEY,lang);var select=document.getElementById("lang-select");if(select)select.value=lang}document.addEventListener("DOMContentLoaded",function(){var initial=detectLanguage();setLanguage(initial);var select=document.getElementById("lang-select");if(select){select.addEventListener("change",function(e){setLanguage(e.target.value)})}var buttons=document.querySelectorAll(".copy-btn");for(var i=0;i<buttons.length;i++){buttons[i].addEventListener("click",function(e){var btn=e.currentTarget;var code=btn.parentElement.querySelector("code");if(!code)return;navigator.clipboard.writeText(code.textContent).then(function(){btn.classList.add("copied");setTimeout(function(){btn.classList.remove("copied")},1500)})})}})})();
